CREATE OR REPLACE PACKAGE BODY scalar_test AS

  FUNCTION count_emp RETURN NUMBER IS
    l_pell_ret_1 NUMBER;
  BEGIN
    BEGIN
      select count(*)
      INTO l_pell_ret_1
      FROM emp;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    RETURN l_pell_ret_1;
  END count_emp;

  FUNCTION first_name RETURN VARCHAR2 IS
    l_n VARCHAR2(4000);
  BEGIN
