      select ename
      INTO l_n
      FROM emp where rownum = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    RETURN l_n;
  END first_name;

  PROCEDURE demo IS
    l_total NUMBER;
  BEGIN
